import os
import assemblyai as aai
import queue

def stream_microphone(payload, config=None):
    config = config or {}

    class MicrophoneStreamGenerator:
        def __init__(self, config):
            aai.settings.api_key = os.environ.get("ASSEMBLYAI_API_KEY")
            if not aai.settings.api_key:
                raise ValueError("ASSEMBLYAI_API_KEY environment variable not set.")

            self.queue = queue.Queue()
            self.closed = False
            self.transcriber = aai.RealtimeTranscriber(
                on_data=self._on_data,
                on_error=self._on_error,
                sample_rate=config.get("sample_rate", 44_100),
            )

        def _on_data(self, transcript: aai.RealtimeTranscript):
            if self.closed:
                return
            if transcript.text:
                self.queue.put(transcript.text)

        def _on_error(self, error: aai.RealtimeError):
            if self.closed:
                return
            self.queue.put(f"Error: {error}")

        def __iter__(self):
            try:
                self.transcriber.connect()
                self.transcriber.stream()
                while self.transcriber.is_connected():
                    try:
                        yield self.queue.get(timeout=1)
                    except queue.Empty:
                        pass
            finally:
                self.closed = True
                self.transcriber.close()

    result = MicrophoneStreamGenerator(config)
    return result
